"""Demo solution for Stage 0 (spot detection pipeline). The admin window can paste it into the editor."""

DEMO_SCRIPT = '# Available API functions:\n#   capture_frame() -> np.ndarray (or None if no camera signal)\n#   set_exposure_ms(ms: float) -> sets exposure time in milliseconds (e.g. 2.0 ms, 5.0 ms)\n#   set_exposure_ev(ev: float) -> sets exposure compensation in EV (e.g. -5.0 EV, -3.0 EV)\n#   set_exposure(val) -> shortcut: ms if val > 0 (e.g. 2.0), EV if val <= 0 (e.g. -5.0)\n#   send_to_screen(frame) or send_to_screen(frame1, frame2) (outputs frames to display)\n#   set_servo_angle(angle: float) -> sets servo position (0.0 to 180.0)\n#   get_servo_angle() -> float (returns current servo angle)\n#   set_detected_spot(x: float, y: float, intensity: float) -> reports spot back to system\n#   send_location(x: float, y: float) -> updates the Spot Location details panel\n#   draw_cross_on_location(img, x, y, size=15, thickness=None) -> returns a copy of the image with a cross drawn at (x, y)\n#   find_spot_center(img) -> returns (x, y) centroid of brightest spot in image\n#   crop_frame(img, x, y, w, h) -> returns cropped image safely from out-of-bounds\n\nimport cv2\nimport numpy as np\nimport time\n\n# Set physical exposure time to 10.0 ms (optimized for laser spot tracking)\nset_exposure_ms(10.0)\n\n# Full calibration and tracking pipeline template:\nwhile True:\n    frame = capture_frame()\n    if frame is not None:\n        # 1. Convert to grayscale\n        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)\n        \n        # 2. Gaussian Blur to reduce noise\n        blurred = cv2.GaussianBlur(gray, (5, 5), 0)\n        \n        # 3. Thresholding\n        _, binary = cv2.threshold(blurred, 200, 255, cv2.THRESH_BINARY)\n        \n        # 4. Detect blobs (contours)\n        contours, _ = cv2.findContours(binary, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)\n        \n        if contours:\n            # Find the largest blob\n            largest_contour = max(contours, key=cv2.contourArea)\n            \n            # Create a mask with only the largest blob\n            mask = np.zeros_like(binary)\n            cv2.drawContours(mask, [largest_contour], -1, 255, -1)\n            \n            # 5. Multiple erosions to shrink the blob to a single point\n            eroded = mask.copy()\n            kernel = np.ones((3, 3), np.uint8)\n            # Erode iteratively until only a few pixels are left\n            for _ in range(10):\n                temp = cv2.erode(eroded, kernel)\n                if np.sum(temp == 255) > 0:\n                    eroded = temp\n                else:\n                    break\n            \n            # 6. Loop through pixels to find the remaining point\n            points = np.argwhere(eroded == 255)\n            if len(points) > 0:\n                # np.argwhere returns [row, col] -> y, x\n                y, x = points[0]\n                \n                # Report spot coordinates and update local panels\n                send_location(x, y)\n                set_detected_spot(x, y, 255.0)\n                \n                # Draw tracking crosshair on the lower (binary) frame only; the camera image stays clean\n                binary = draw_cross_on_location(binary, x, y, size=100)\n            else:\n                send_location(-1.0, -1.0)\n                set_detected_spot(-1.0, -1.0, 0.0)\n        else:\n            send_location(-1.0, -1.0)\n            set_detected_spot(-1.0, -1.0, 0.0)\n                \n        # Display stacked original and binary output (forms 16x18 display layout)\n        send_to_screen(frame, binary)\n        \n    time.sleep(0.01)\n'
